def has_surrogates(utf8):
    pos = 0
    while True:
        pos = utf8.find('í', pos)
        if pos < 0:
            return False
        assert pos <= len(utf8) - 1
        ordch2 = ord(utf8[pos + 1])
        if _invalid_byte_2_of_3(237, ordch2, allow_surrogates=False):
            return True
        pos += 1
    return False

