def load_library(library_name, install_instructions_string=None):
    try:
        loaded_module = importlib.import_module(library_name)
        return True
    except ModuleNotFoundError as e:
        if install_instructions_string:
            cli_message('<red>ERROR: Great Expectations relies on the library `{}` to connect to your data.</red>\n            - Please `{}` before trying again.'.format(library_name, install_instructions_string))
        else:
            cli_message('<red>ERROR: Great Expectations relies on the library `{}` to connect to your data.</red>\n      - Please `pip install {}` before trying again.'.format(library_name, library_name))
        return False

