def _check_changed_nodes(self):
    for node_b in self._topo_b_nodes:
        node_a = self._identical_nodes.get(node_b)
        if node_a:
            if self._graph_b.get_node_version(node_b) != self._graph_a.get_node_version(node_a) or self._graph_b.get_node_parents(node_b) != self._graph_a.get_node_parents(node_a) or self._graph_b.get_node_inputs(node_b) != self._graph_a.get_node_inputs(node_a):
                self._changed_nodes[node_b] = node_a

