    self._matched_recipe_inputs = {}
    self._identical_nodes = {}
    self._changed_nodes = {}
    self._new_nodes = set()
    self._deleted_nodes = set()
    self._topo_a_nodes = self._graph_a.get_topological_order()
    self._topo_b_nodes = self._graph_b.get_topological_order()
    self._unresolved_a_nodes = set(self._topo_a_nodes)
    self._unresolved_b_nodes = set(self._topo_b_nodes)
    self._match_recipe_inputs()
    if not self.can_be_reprocessed:
        return
    self._match_identical_nodes()
    for node_b in self._topo_b_nodes:
        node_a = self._graph_a.get_node(node_b)
        if node_a is None:
            self._new_nodes.add(node_b)
        elif self._graph_a.get_node_version(node_a) != self._graph_b.get_node_version(node_b) or self._graph_a.get_node_parents(node_a) != self._graph_b.get_node_parents(node_b) or self._graph_a.get_node_inputs(node_a) != self._graph_b.get_node_inputs(node_b):
            self._changed_nodes[node_b] = node_a
    self._deleted_nodes = self._unresolved_a_nodes
    self._unresolved_a_nodes = set()
    self._unresolved_b_nodes = set()

