def _get_server_certificate_provider(self, pc_instance: PrivateComputationInstance) -> CertificateProvider:
    if pc_instance.infra_config.role == PrivateComputationRole.PUBLISHER and pc_instance.has_feature(PCSFeature.PCF_TLS):
        return PCInstanceServerCertificateProvider(pc_instance)
    else:
        return NullCertificateProvider()

