def filter_documents(self, filters: Optional[Dict[str, Any]]=None) -> List[Document]:
    if filters:
        if not isinstance(filters, dict):
            msg = 'Filters must be a dictionary'
            raise TypeError(msg)
        if 'operator' not in filters and 'conditions' not in filters:
            filters = convert(filters)
    sql_filter = SQL('SELECT * FROM {table_name}').format(table_name=Identifier(self.table_name))
    params = ()
    if filters:
        (sql_where_clause, params) = _convert_filters_to_where_clause_and_params(filters)
        sql_filter += sql_where_clause
    result = self._execute_sql(sql_filter, params, error_msg='Could not filter documents from PgvectorDocumentStore.', cursor=self._dict_cursor)
    records = result.fetchall()
    docs = self._from_pg_to_haystack_documents(records)
    return docs

round_1_repaired_code:
def filter_documents(self, filters: Optional[Dict[str, Any]]=None) -> List[Document]:
    sql_get_docs = SQL('SELECT * FROM {table_name} WHERE {filter_conditions}').format(table_name=Identifier(self.table_name), filter_conditions=self._build_filter_conditions(filters))
    result = self._execute_sql(sql_get_docs, error_msg='Could not filter documents from PgvectorDocumentStore', cursor=self._dict_cursor)
    records = result.fetchall()
    docs = self._from_pg_to_haystack_documents(records)
    return docs

def _build_filter_conditions(self, filters: Optional[Dict[str, Any]]) -> str:
    if not filters:
        return '1=1'
    conditions = []
    for (key, value) in filters.items():
        conditions.append(f"{key} = '{value}'")
    return ' AND '.join(conditions)

