                        if abs(base_center[0] - aa_center[0]) < dist_cent_cutoff and abs(base_center[1] - aa_center[1]) < dist_cent_cutoff and (distance_between_vectors(base_center, aa_center) < dist_cent_cutoff) and enough_near_contacts(base_residue, aa_residue, base_atoms, num_near_contacts_needed):
                            count_pair = count_pair + 1
