def set_writes_colorspace(self, write_dict):
    if not isinstance(write_dict, dict):
        msg = 'set_root_colorspace(): argument should be dictionary'
        nuke.message(msg)
        log.error(msg)
        return
    log.debug('__ set_writes_colorspace(): {}'.format(write_dict))
    colorspace_presets = {'HD': 'sRGB', '4K': 'Rec. 2020', '2K': 'Rec. 709'}
    for node in write_dict.get('nodes', []):
        if node.get('type') == 'Write':
            project_resolution = node.get('resolution', 'HD')
            colorspace = colorspace_presets.get(project_resolution, 'sRGB')
            node['colorspace'] = colorspace
            log.info(f"Set colorspace for node {node['name']} to {colorspace}")

