def depths(self):
    depths = {}

    def update_depths(node, curr_depth):
        depths[node] = curr_depth
        for child in node.clades:
            new_depth = curr_depth + child.branch_length
            update_depths(child, new_depth)
    update_depths(self.root, 0)
    return depths

round_1_repaired_code:
def depths(self):
    depths = {}
    queue = [(self.root, 0)]
    while queue:
        (node, depth) = queue.pop(0)
        depths[node.clade] = depth
        for child in node.children:
            queue.append((child, depth + child.branch_length))
    return depths

