            asset = Asset(url, cache_dirs=CACHE_DIRS)
            asset.fetch()
        except OSError:
            LOG.error('Failed to fetch setuptools egg for Python version %s', version)
            return 1
    return 0

def commit(self) -> None:
    self._flush_rpsl_object_upsert_cache()
    self.status_tracker.finalise_transaction()
    try:
        self._transaction.commit()
        self._start_transaction()
    except Exception as exc:
        self._transaction.rollback()
        logger.critical('Exception occurred while committing changes, rolling back', exc_info=exc)
        raise

