def position(self):
    now_playing = self._setstate.nowPlayingInfo
    if now_playing.HasField('elapsedTime'):
        return int(now_playing.elapsedTime)
    return None

processed_final_repaired_code:
def position(self):
    timestamp = int(self._setstate.nowPlayingInfo.timestamp)
    if timestamp == 0:
        return 0
    now_utc = datetime.datetime.utcnow()
    timeshift = datetime.datetime(2001, 1, 1, 0, 0) + datetime.timedelta(seconds=timestamp)
    diff = (now_utc - timeshift).total_seconds()
    base = self._setstate.nowPlayingInfo.elapsedTime
    return int(base + diff) if int(self._setstate.nowPlayingInfo.playbackRate) == 0 else int(base)

