def _startupConfigBrowserSlot(self):
    if hasattr(sys, 'frozen'):
        config_dir = 'configs'
    else:
        config_dir = pkg_resources.resource_filename('gns3', 'configs')
    path = QtGui.QFileDialog.getOpenFileName(self, 'Select a startup configuration', config_dir)
    if not path:
