def unit_positions(df: pd.DataFrame, cids: List[str], xcat_sig: str, start: str=None, end: str=None, scale: str='prop', min_obs: int=252, thresh: float=None):
    options = ['prop', 'dig']
    assert scale in options, f'The scale parameter must be either {options}'
    if scale == 'prop':
        assert isinstance(min_obs, int), 'Minimum observation parameter must be an integer.'
        df_up = make_zn_scores(df, xcat=xcat_sig, sequential=True, cids=cids, start=start, end=end, neutral='zero', pan_weight=1, min_obs=min_obs, thresh=thresh)
    else:
        df_up = reduce_df(df=df, xcats=[xcat_sig], cids=cids, start=start, end=end, blacklist=None)
        df_up['value'] = np.sign(df_up['value'])
    return df_up

