def _render_topic(self, topic: str, icons: Tuple[Icon, Icon]):
    html.open_h2()
    html.div(class_='spacer', content='')
    if not config.user.get_attribute('icons_per_item'):
        html.icon(icons[0])
    else:
        html.icon(icons[1])
    html.span(topic)
    html.close_h2()

def call(self, cmdtype_msg: Tuple[str, Optional[bytes]], timeout: Optional[int]=None) -> Tuple[Result, str]:
    assert self.xml is not None
    if not self.running():
        raise CoqtopError('Coqtop is not running.')
    self.empty_out()
    (cmd, msg) = cmdtype_msg
    if msg is None:
        return (self.xml.standardize(cmd, Ok(None)), self.collect_err())
    if self.logger.isEnabledFor(logging.DEBUG):
        self.logger.debug(prettyxml(msg))
    self.send_cmd(msg)
    with futures.ThreadPoolExecutor(1) as pool:
        try:
            timeout = timeout if timeout != 0 else None
            response = pool.submit(self.get_answer).result(timeout)
        except futures.TimeoutError:
            self.interrupt()
            response = TIMEOUT_ERR
    return (self.xml.standardize(cmd, response), self.collect_err())

