def _RunInstrumentCommand(command, options, args, option_parser):
    if not (options.input_path and options.output_path and options.coverage_file and options.sources_file and options.sources and options.src_root and options.emma_jar):
        option_parser.error('All arguments are required.')
    coverage_file = os.path.join(os.path.dirname(options.output_path), options.coverage_file)
    sources_file = os.path.join(os.path.dirname(options.output_path), options.sources_file)
    temp_dir = tempfile.mkdtemp()
    try:
        cmd = ['java', '-cp', options.emma_jar, 'emma', 'instr', '-ip', options.input_path, '-ix', options.filter_string, '-d', temp_dir, '-out', coverage_file, '-m', 'fullcopy']
        build_utils.CheckCallDie(cmd, suppress_output=True)
        if command == 'instrument_jar':
            for jar in os.listdir(os.path.join(temp_dir, 'lib')):
                shutil.copy(os.path.join(temp_dir, 'lib', jar), options.output_path)
        else:
            if os.path.isdir(options.output_path):
                shutil.rmtree(options.output_path, ignore_errors=True)
            shutil.copytree(os.path.join(temp_dir, 'classes'), options.output_path)
    finally:
        shutil.rmtree(temp_dir)
    _CreateSourcesFile(options.sources, sources_file, options.src_root)
    if options.stamp:
        build_utils.Touch(options.stamp)
    return 0

