def create_machine(session, machine, dblocation, dbmodel, cpuname, cpuvendor, cpuspeed, cpucount, memory, serial):
    dbcpu = None
    if not (cpuname or cpuvendor or cpuspeed is not None):
        if not dbmodel.machine_specs:
            raise ArgumentError('Model %s does not have machine specification defaults, please specify --cpuvendor, --cpuname, and --cpuspeed.' % dbmodel.name)
        dbcpu = dbmodel.machine_specs.cpu
    else:
        q = session.query(Cpu)
        if cpuname:
            q = q.filter(Cpu.name.like(cpuname.lower() + '%'))
        if cpuspeed is not None:
            q = q.filter_by(speed=cpuspeed)
        if cpuvendor:
            q = q.join('vendor').filter_by(name=cpuvendor.lower())
        cpulist = q.all()
        if not cpulist:
            raise ArgumentError('Could not find a CPU with the given attributes.')
        if len(cpulist) == 1:
            dbcpu = cpulist[0]
        elif dbmodel.machine_specs:
            dbcpu = dbmodel.machine_specs.cpu
            if cpuname and (not dbcpu.name.startswith(cpuname.lower())) or (cpuspeed is not None and dbcpu.speed != cpuspeed) or (cpuvendor and dbcpu.vendor.name != cpuvendor.lower()):
                raise ArgumentError('Could not uniquely identify a CPU with the attributes given.')
        else:
            raise ArgumentError('Could not uniquely identify a CPU with the attributes given.')
    if cpucount is None:
        if dbmodel.machine_specs:
            cpucount = dbmodel.machine_specs.cpu_quantity
        else:
            raise ArgumentError('Model %s does not have machine specification defaults, please specify --cpucount.' % dbmodel.name)
    if memory is None:
        if dbmodel.machine_specs:
            memory = dbmodel.machine_specs.memory
        else:
            raise ArgumentError('Model %s does not have machine specification defaults, please specify --memory (in MB).' % dbmodel.name)
    dbmachine = Machine(location=dblocation, model=dbmodel, name=machine, cpu=dbcpu, cpu_quantity=cpucount, memory=memory, serial_no=serial)
    session.add(dbmachine)
    if dbmodel.machine_specs and dbmodel.machine_type != 'aurora_node' and (dbmodel.machine_specs.disk_type == 'local'):
        specs = dbmodel.machine_specs
        dbdisk = LocalDisk(machine=dbmachine, device_name=specs.disk_name, controller_type=specs.controller_type, capacity=specs.disk_capacity)
        session.add(dbdisk)
    session.flush()
    return dbmachine

