        model_path = os.path.join(self._serialization_dir, 'model_state_eval_best.th')
    else:
        best_str = '.best_macro' if new_best_macro else ''
        model_path = os.path.join(self._serialization_dir, 'model_state_{}_epoch_{}{}.th'.format(phase, epoch, best_str))
    model_state = self._model.state_dict()
    keys_to_skip = [key for key in model_state if dont_save(key)]
    for key in keys_to_skip:
        del model_state[key]
    torch.save(model_state, model_path)
    if phase != 'eval':
        torch.save(training_state, os.path.join(self._serialization_dir, 'training_state_{}_epoch_{}{}.th'.format(phase, epoch, best_str)))
        task_states = {}
        for (task_name, task_info) in self._task_infos.items():
            task_states[task_name] = {'total_batches_trained': task_info['total_batches_trained'], 'stopped': task_info['stopped'], 'optimizer': task_info['optimizer'].state_dict(), 'scheduler': {}}
        task_states['global'] = {'optimizer': self._g_optimizer.state_dict() if self._g_optimizer is not None else None, 'scheduler': {} if self._g_scheduler is not None else None}
        torch.save(task_states, os.path.join(self._serialization_dir, 'task_state_{}_epoch_{}{}.th'.format(phase, epoch, best_str)))
        metric_states = {}
        for (metric_name, metric_info) in self._metric_infos.items():
            metric_states[metric_name] = {'hist': metric_info['hist'], 'stopped': metric_info['stopped'], 'best': metric_info['best']}
        torch.save(metric_states, os.path.join(self._serialization_dir, 'metric_state_{}_epoch_{}{}.th'.format(phase, epoch, best_str)))
    log.info('Saved files to %s', self._serialization_dir)
    if phase != 'eval' and new_best_macro:
        self._unmark_previous_best(phase, epoch)
    if not self._keep_all_checkpoints:
        self._delete_old_checkpoints(phase, epoch)

