def accounts(self, network=None):
    if self.multisig:
        raise WalletError('Accounts not supported for multisig wallets')
    else:
        accounts = []
        wks = self.keys_accounts(network=network)
        for wk in wks:
            accounts.append(HDWalletKey(wk.id, self._session))
    return accounts

