def __init__(self, path, mode='rt', schema=None, columns=None, types=None, hints=None, dialect=None, header=None, open=open, nrows_discovery=50, **kwargs):
    if 'r' in mode and os.path.isfile(path) is not True:
        raise ValueError('CSV file "%s" does not exist' % path)
    if not schema and 'w' in mode:
        raise ValueError('Please specify schema for writable CSV file')
    self.path = path
    self.mode = mode
    self.open = open
    if os.path.exists(path) and mode != 'w':
        f = self.open(path, 'rt')
        sample = f.read(1024)
        try:
            f.close()
        except AttributeError:
            pass
    else:
        sample = ''
    dialect = discover_dialect(sample, dialect, **kwargs)
    assert dialect
    if header is None:
        header = has_header(sample)
    if not schema and 'w' not in mode:
        if not types:
            with open(self.path, 'r') as f:
                data = list(it.islice(csv.reader(f, **dialect), 1, nrows_discovery))
                types = discover(data)
                rowtype = types.subshape[0]
                if isinstance(rowtype[0], Tuple):
                    types = types.subshape[0][0].dshapes
                    types = [t.ty if isinstance(t, Option) else t for t in types]
                    types = [string if t == null else t for t in types]
                elif isinstance(rowtype[0], Fixed) and isinstance(rowtype[1], CType):
                    types = int(rowtype[0]) * [rowtype[1]]
                else:
                    ValueError('Could not discover schema from data.\nPlease specify schema.')
        if not columns:
            if header:
                with open(self.path, 'r') as f:
                    columns = next(csv.reader([next(f)], **dialect))
            else:
                columns = ['_%d' % i for i in range(len(types))]
        if hints:
            types = [hints.get(c, t) for (c, t) in zip(columns, types)]
        schema = dshape(Record(list(zip(columns, types))))
    self._schema = schema
    self.header = header
    self.dialect = dialect

