def apply(self, func, is_volume=False, in_place=True, verbose: bool=False, n_processes: Optional[int]=None, **kwargs) -> 'ImageStack':
    if not in_place:
        image_stack = deepcopy(self)
        return image_stack.apply(func, is_volume=is_volume, in_place=True, verbose=verbose, **kwargs)
    if is_volume:
        self._data = self._data.stack(tiles=[Indices.ROUND.value, Indices.CH.value])
    else:
        self._data = self._data.stack(tiles=[Indices.ROUND.value, Indices.CH.value, Indices.Z.value])
    tile_indices = self._data.tiles
    applyfunc: Callable = partial(func, **kwargs)
    progress_func = tqdm if verbose else lambda f: f
    tiles = (self._data.sel(tiles=t) for t in tile_indices)
    with multiprocessing.Pool(n_processes) as pool:
        results = zip(progress_func(pool.imap(applyfunc, tiles)), tile_indices)
        for (result, t) in results:
            self._data.loc[{'tiles': t}] = result
    self._data = self._data.unstack('tiles').transpose(Indices.ROUND.value, Indices.CH.value, Indices.Z.value, 'y', 'x')
    return self

