    data = {'name': self._timeline_name, 'sketch_id': self._sketch.id, 'enable_stream': not end_stream, 'data_label': self._data_label, 'provider': self._provider, 'events': data_frame.to_json(orient='records', lines=True)}
    if self._index:
        data['index_name'] = self._index
    if self._upload_context:
        data['context'] = self._upload_context
    response = self._sketch.api.session.post(self._resource_url, data=data)
    if response.status_code not in definitions.HTTP_STATUS_CODE_20X:
        if retry_count >= self.DEFAULT_RETRY_LIMIT:
            raise RuntimeError('Error uploading data: [{0:d}] {1!s} {2!s}, index {3:s}'.format(response.status_code, response.reason, response.text, self._index))
        logger.warning('Unable to upload dataframe, retrying (attempt {0:d}/{1:d})'.format(retry_count + 1, self.DEFAULT_RETRY_LIMIT))
        return self._upload_data_frame(data_frame=data_frame, end_stream=end_stream, retry_count=retry_count + 1)
    self._chunk += 1
    response_dict = response.json()
    object_dict = response_dict.get('objects', [{}])[0]
    meta_dict = response_dict.get('meta', {})
    self._celery_task_id = meta_dict.get('task_id', '')
    self._timeline_id = object_dict.get('id')
    self._index = object_dict.get('searchindex', {}).get('index_name')
    self._last_response = response_dict
    return None

