def action(self) -> ActionResult:
    if html.request.var('_reset'):
        if not transactions.check_transaction():
            return None
        try:
            del self._current_settings[self._varname]
        except KeyError:
            pass
        msg = html.render_text(_('Resetted configuration variable %s to its default.') % self._varname)
    else:
        new_value = self._valuespec.from_html_vars('ve')
        self._valuespec.validate_value(new_value, 've')
        self._current_settings[self._varname] = new_value
        msg = HTML(_('Changed global configuration variable %s to %s.') % (escaping.escape_attribute(self._varname), self._valuespec.value_to_text(new_value)))
    self._save()
    watolib.add_change('edit-configvar', msg, sites=self._affected_sites(), domains=[self._config_variable.domain()], need_restart=self._config_variable.need_restart())
    return redirect(self._back_url())

