        parts = _split_into_chars(self, maxsplit)
    try:
        return W_UnicodeObject(w_new._value.join(parts))
    except MemoryError:
        raise OperationError(space.w_OverflowError, space.wrap('replace string is too long'))
    except OverflowError:
        raise OperationError(space.w_OverflowError, space.wrap('replace string is too long'))

