def build_model_delta_optimizer_process(model_fn: _ModelConstructor, model_to_client_delta_fn: Callable[[Callable[[], model_lib.Model]], ClientDeltaFn], server_optimizer_fn: _OptimizerConstructor, *, broadcast_process: Optional[measured_process.MeasuredProcess]=None, model_update_aggregation_factory: Optional[factory.AggregationFactory]=None) -> iterative_process.IterativeProcess:
    py_typecheck.check_callable(model_fn)
    py_typecheck.check_callable(model_to_client_delta_fn)
    py_typecheck.check_callable(server_optimizer_fn)
    model_weights_type = model_utils.weights_type_from_model(model_fn)
    if broadcast_process is None:
        broadcast_process = build_stateless_broadcaster(model_weights_type=model_weights_type)
    if not _is_valid_broadcast_process(broadcast_process):
        raise ProcessTypeError('broadcast_process type signature does not conform to expected signature (<state@S, input@S> -> <state@S, result@C, measurements@S>). Got: {t}'.format(t=broadcast_process.next.type_signature))
    if model_update_aggregation_factory is not None:
        py_typecheck.check_type(model_update_aggregation_factory, factory.AggregationFactory.__args__)
        if isinstance(model_update_aggregation_factory, factory.WeightedAggregationFactory):
            aggregation_process = model_update_aggregation_factory.create(model_weights_type.trainable, computation_types.TensorType(tf.float32))
        else:
            aggregation_process = model_update_aggregation_factory.create(model_weights_type.trainable)
        process_signature = aggregation_process.next.type_signature
        input_client_value_type = process_signature.parameter[1]
        result_server_value_type = process_signature.result[1]
        if input_client_value_type.member != result_server_value_type.member:
            raise TypeError(f'`model_update_aggregation_factory` does not produce a compatible `AggregationProcess`. The processes must retain the type structure of the inputs on the server, but got {input_client_value_type.member} != {result_server_value_type.member}.')
    initialize_computation = _build_initialize_computation(model_fn=model_fn, server_optimizer_fn=server_optimizer_fn, broadcast_process=broadcast_process, aggregation_process=aggregation_process)
    run_one_round_computation = _build_one_round_computation(model_fn=model_fn, server_optimizer_fn=server_optimizer_fn, model_to_client_delta_fn=model_to_client_delta_fn, broadcast_process=broadcast_process, aggregation_process=aggregation_process)
    return iterative_process.IterativeProcess(initialize_fn=initialize_computation, next_fn=run_one_round_computation)

