                if self.done:
                    logger.info('Acquirer is exiting')
                    return
            except Exception as e:
                logger.error('Acquirer exception during run: {}'.format(e))
                break
        elif signal == 'pause':
            logger.info('Acquirer is paused')
            time.sleep(1)
        elif signal == 'stop':
            logger.info('Acquirer is stopping')
