def forward_unbatched(self, x, mask=None, *, weights, state, update_state, rng):
    del update_state
    if self.share_qk:
        (w_q, w_v, w_o) = weights
    else:
        (w_q, w_k, w_v, w_o) = weights
    q = np.matmul(x, w_q)
    k = None
    if not self.share_qk:
        k = np.matmul(x, w_k)
    v = np.matmul(x, w_v)
    mask_fn = functools.partial(mask_self_attention, causal=self.causal, exclude_self=self.share_qk, masked=self.masked)
    q_info = kv_info = jax.lax.tie_in(x, np.arange(q.shape[-2]))
    assert (mask is not None) == self.masked
    if self.masked:
        ones_like_mask = jax.lax.tie_in(x, np.ones_like(mask, dtype=np.int32))
        kv_info = kv_info * np.where(mask, ones_like_mask, -ones_like_mask)
    (o, _) = attend(q, k, v, q_chunk_len=self.chunk_len, kv_chunk_len=self.chunk_len, n_chunks_before=self.n_chunks_before, n_chunks_after=self.n_chunks_after, mask_fn=mask_fn, q_info=q_info, kv_info=kv_info, dropout=self.attention_dropout, rng=rng)
    out = np.matmul(o, w_o)
    return (out, state)

