def windowize_function(expr, default_frame):
    func = var('func')
    frame = var('frame')
    wrap_analytic = (p.Analytic | p.Reduction) >> c.WindowFunction(_, default_frame)
    merge_frames = p.WindowFunction(func, frame) >> c.WindowFunction(func, frame.copy(order_by=frame.order_by + default_frame.order_by, group_by=frame.group_by + default_frame.group_by))
    node = expr.op()
    node = node.replace(merge_frames, filter=p.Value)
    node = node.replace(wrap_analytic, filter=p.Value & ~p.WindowFunction)
    return node.to_expr()

