import networkx as nx

def find_workflow_tasks(wb_dsl, target_task_name):
    G = nx.DiGraph()
    for task in wb_dsl:
        G.add_node(task['name'])
        for dependency in task.get('dependencies', []):
            G.add_edge(dependency, task['name'])
    return list(nx.topological_sort(G)) if target_task_name in G else None

