def get_price(self, to_asset: Asset, block_identifier: BlockIdentifier) -> Price:
    log.debug(f'Querying saddle for price of {from_asset} to {to_asset}')
    if from_asset != A_ALETH:
        raise PriceQueryUnsupportedAsset(f'{from_asset} is not a valid asset for the Saddle oracle')
    aleth_eth_price = SADDLE_ALETH_POOL.call(ethereum=self.eth_manager, method_name='calculateSwap', arguments=[1, 0, 1000000000000000000], block_identifier=block_identifier)
    aleth_eth_price /= EXP18
    if to_asset not in (A_WETH, A_ETH):
        eth_price = Inquirer().find_price(A_ETH, to_asset)
        return aleth_eth_price * eth_price
    return aleth_eth_price

