    timeline_dict = response_dict['objects'][0]
    timeline_obj = timeline.Timeline(timeline_id=timeline_dict['id'], sketch_id=self.id, api=self.api, name=timeline_dict['name'], searchindex=timeline_dict['searchindex']['index_name'])
