async def handle(self, command_name: str, data: Dict[str, Any], requested_command: Optional[Union[Command, OldCommand]]) -> None:
    if requested_command and isinstance(requested_command, Command):
        requested_command.handle_requested(self.events, data)
    else:
        command_name = re.sub(_COMMAND_REPLACE_PATTERN, _COMMAND_REPLACE_REPLACEMENT, command_name)
        command = COMMANDS.get(command_name, None)
        if command:
            command.handle(self.events, data)
        else:
            await self._handle_old(command_name, data, requested_command is not None)

