async def _handle_graphql_message(self, source: 'u.User', intent: IntentAPI, message: graphql.Message) -> List[EventID]:
    reply_to_id = message.replied_to_message.message.message_id if message.replied_to_message else None
    event_ids = []
    if message.sticker:
        event_ids.append(await self._handle_facebook_sticker(source, intent, int(message.sticker.id), reply_to_id, message.timestamp))
    if len(message.blob_attachments) > 0:
        attach_ids = await asyncio.gather(*[self._handle_facebook_attachment(message.message_id, source, intent, attachment, reply_to_id, message.timestamp) for attachment in message.blob_attachments])
        event_ids += [attach_id for attach_id in attach_ids if attach_id]
    if message.extensible_attachment:
        sa = message.extensible_attachment.story_attachment
        content = await self._convert_extensible_media(source, intent, sa)
        if content:
            event_ids.append(await self._send_message(intent, content, timestamp=message.timestamp))
    if message.message and message.message.text:
        event_ids.append(await self._handle_facebook_text(intent, message.message, reply_to_id, message.timestamp))
    return event_ids

