def normalize(host_string, omit_port=False):
    if not host_string:
        return ('', '') if omit_port else ('', '', '')
    r = host_regex.match(host_string).groupdict()
    host = r['host']
    user = env.user
    port = env.port
    if env.use_ssh_config:
        conf = ssh_config().lookup(host)
        if user == env.local_user and 'user' in conf:
            user = conf['user']
        if port == env.default_port and 'port' in conf:
            port = conf['port']
        if 'hostname' in conf:
            host = conf['hostname']
    user = r['user'] or user
    port = r['port'] or port
    if omit_port:
        return (user, host)
    return (user, host, port)

