        msg = _('Volume %(share_name)s does not exist on vserver % (vserver)s.')
        msg_args = {'share_name': share_name, 'vserver': vserver}
        raise exception.ShareResourceNotFound(msg % msg_args)
    if active_replica['status'] == constants.STATUS_REVERTING:
        return None
    dm_session = data_motion.DataMotionSession()
    try:
        snapmirrors = dm_session.get_snapmirrors(active_replica, replica)
    except netapp_api.NaApiError:
        LOG.exception('Could not get snapmirrors for replica %s.', replica['id'])
        return constants.STATUS_ERROR
    is_readable = replication and self._is_readable_replica(replica)
    if not snapmirrors:
        if replica['status'] != constants.STATUS_CREATING:
            try:
                pool_name = share_utils.extract_host(replica['host'], level='pool')
                relationship_type = na_utils.get_relationship_type(self._is_flexgroup_pool(pool_name))
                dm_session.create_snapmirror(active_replica, replica, relationship_type, mount=is_readable)
            except netapp_api.NaApiError:
                LOG.exception('Could not create snapmirror for replica %s.', replica['id'])
                return constants.STATUS_ERROR
        return constants.REPLICA_STATE_OUT_OF_SYNC
    snapmirror = snapmirrors[0]
    in_progress_status = ['preparing', 'transferring', 'finalizing']
    if snapmirror.get('mirror-state') != 'snapmirrored' and snapmirror.get('relationship-status') in in_progress_status:
        return constants.REPLICA_STATE_OUT_OF_SYNC
    if snapmirror.get('mirror-state') != 'snapmirrored':
        try:
            vserver_client.resume_snapmirror_vol(snapmirror['source-vserver'], snapmirror['source-volume'], vserver, share_name)
            vserver_client.resync_snapmirror_vol(snapmirror['source-vserver'], snapmirror['source-volume'], vserver, share_name)
            return constants.REPLICA_STATE_OUT_OF_SYNC
        except netapp_api.NaApiError:
            LOG.exception('Could not resync snapmirror.')
            return constants.STATUS_ERROR
    last_update_timestamp = float(snapmirror.get('last-transfer-end-timestamp', 0))
    if last_update_timestamp and timeutils.is_older_than(datetime.datetime.utcfromtimestamp(last_update_timestamp).isoformat(), 3600):
        return constants.REPLICA_STATE_OUT_OF_SYNC
    replica_backend = share_utils.extract_host(replica['host'], level='backend_name')
    config = data_motion.get_backend_configuration(replica_backend)
    config_size = int(config.safe_get('netapp_snapmirror_last_transfer_size_limit')) * units.Ki
    last_transfer_size = int(snapmirror.get('last-transfer-size', 0))
    if last_transfer_size > config_size:
        return constants.REPLICA_STATE_OUT_OF_SYNC
    last_transfer_error = snapmirror.get('last-transfer-error', None)
    if last_transfer_error:
        LOG.debug('Found last-transfer-error: %(error)s for replica: %(replica)s.', {'replica': replica['id'], 'error': last_transfer_error})
        return constants.REPLICA_STATE_OUT_OF_SYNC
    snapshots = [snap['share_replica_snapshot'] for snap in share_snapshots]
    for snap in snapshots:
        snapshot_name = snap.get('provider_location')
        if not snapshot_name or not vserver_client.snapshot_exists(snapshot_name, share_name):
            return constants.REPLICA_STATE_OUT_OF_SYNC
    return constants.REPLICA_STATE_IN_SYNC

