def get_resources(self, user=None, project=None, source=None, start_timestamp=None, start_timestamp_op=None, end_timestamp=None, end_timestamp_op=None, metaquery=None, resource=None, pagination=None):
    if pagination:
        raise NotImplementedError('Pagination not implemented')
    metaquery = metaquery or {}

    def _apply_filters(query):
        for (column, value) in [(models.Sample.resource_id, resource), (models.Sample.user_id, user), (models.Sample.project_id, project), (models.Sample.source_id, source)]:
            if value:
                query = query.filter(column == value)
        if metaquery:
            query = apply_metaquery_filter(session, query, metaquery)
        if start_timestamp:
            if start_timestamp_op == 'gt':
                query = query.filter(models.Sample.timestamp > start_timestamp)
            else:
                query = query.filter(models.Sample.timestamp >= start_timestamp)
        if end_timestamp:
            if end_timestamp_op == 'le':
                query = query.filter(models.Sample.timestamp <= end_timestamp)
            else:
                query = query.filter(models.Sample.timestamp < end_timestamp)
        return query
    session = self._engine_facade.get_session()
    res_q = session.query(distinct(models.Sample.resource_id))
    res_q = _apply_filters(res_q)
    for res_id in res_q.all():
        max_q = session.query(models.Sample).filter(models.Sample.resource_id == res_id[0])
        max_q = _apply_filters(max_q)
        max_q = max_q.order_by(models.Sample.timestamp.desc(), models.Sample.id.desc()).limit(1)
        min_q = session.query(models.Sample.timestamp).filter(models.Sample.resource_id == res_id[0])
        min_q = _apply_filters(min_q)
        min_q = min_q.order_by(models.Sample.timestamp.asc()).limit(1)
        sample = max_q.first()
        if sample:
            yield api_models.Resource(resource_id=sample.resource_id, project_id=sample.project_id, first_sample_timestamp=min_q.first().timestamp, last_sample_timestamp=sample.timestamp, source=sample.source_id, user_id=sample.user_id, metadata=sample.resource_metadata)

