def transitive_closure(self):
    from copy import copy
    G = self.copy(immutable=False)
    G.name('Transitive closure of ' + self.name())
    for v in G:
        for e in G.breadth_first_search(v):
            if not G.has_edge((v, e)):
                G.add_edge((v, e))
    return G

