def __init__(self, config, coherence_instance):
    log.Loggable.__init__(self)
    self._tube_proxies = []
    self._coherence = coherence_instance
    chatroom = config['chatroom']
    manager = config['manager']
    protocol = config['protocol']
    account = config['account']
    if isinstance(account, basestring):
        bus = dbus.SessionBus()
        account_obj = bus.get_object(ACCOUNT_MANAGER, account)
        account = account_obj.Get(ACCOUNT, 'Parameters')
    if manager == 'gabble' and 'fallback-conference-server' not in account:
        account['fallback-conference-server'] = 'conference.jabber.org'
    if 'fallback-conference-server' in account:
        print(f"Advertising fallback conference server: {account['fallback-conference-server']}")
    try:
        allowed_devices = config['allowed_devices'].split(',')
    except KeyError:
        allowed_devices = None
    tubes_to_offer = {BUS_NAME: {}, DEVICE_IFACE: {}, SERVICE_IFACE: {}}
    callbacks = dict(found_peer_callback=self.found_peer, disapeared_peer_callback=self.disapeared_peer, got_devices_callback=self.got_devices)
    self._tube_publisher = MirabeauTubePublisherConsumer(manager, protocol, account, chatroom, tubes_to_offer, self._coherence, allowed_devices, **callbacks)

