def _real_extract(self, url):
    (video_type, video_id, display_id) = re.match(self._VALID_URL, url).groups()
    webpage = self._download_webpage(url, display_id)
    self._search_auth_key(webpage)
    video_json = self._call_api('https://api.rctiplus.com/api/v1/%s/%s/url?appierid=.1' % (video_type, video_id), display_id, 'Downloading video URL JSON')[0]
    video_url = video_json['url']
    if 'akamaized' in video_url:
        conviva_json_data = {**self._CONVIVA_JSON_TEMPLATE, 'url': video_url, 'sst': int(time.time())}
        conviva_json_res = self._download_json('https://ff84ae928c3b33064b76dec08f12500465e59a6f.cws.conviva.com/0/wsg', display_id, 'Creating Conviva session', 'Failed to create Conviva session', fatal=False, data=json.dumps(conviva_json_data).encode('utf-8'))
        if conviva_json_res and conviva_json_res.get('err') != 'ok':
            self.report_warning('Conviva said: %s' % str(conviva_json_res.get('err')))
    (video_meta, meta_paths) = self._call_api('https://api.rctiplus.com/api/v1/%s/%s' % (video_type, video_id), display_id, 'Downloading video metadata')
    (thumbnails, image_path) = ([], meta_paths.get('image_path', 'https://rstatic.akamaized.net/media/'))
    if video_meta.get('portrait_image'):
        thumbnails.append({'id': 'portrait_image', 'url': '%s%d%s' % (image_path, 2000, video_meta['portrait_image'])})
    if video_meta.get('landscape_image'):
        thumbnails.append({'id': 'landscape_image', 'url': '%s%d%s' % (image_path, 2000, video_meta['landscape_image'])})
    formats = self._extract_m3u8_formats(video_url, display_id, 'mp4', headers={'Referer': 'https://www.rctiplus.com/'})
    for f in formats:
        if 'akamaized' in f['url']:
