def close(self):
    with self._server.lock:
        for subs in self._server.subscribers.values():
            subs.discard(self)
        for subs in self._server.psubscribers.values():
            subs.discard(self)
        self._clear_watches()
    self._server = None
    self._db = None
    self.responses = None

