            elif isinstance(node, ast.Field) and isinstance(parent_node, ast.JoinExpr):
                if len(node.chain) == 1:
                    table_names = database.get_all_tables()
                    extend_responses(keys=table_names, suggestions=response.suggestions, kind=Kind.Folder, details=['Table'] * len(table_names))
        except Exception:
            pass
        if len(response.suggestions) != 0:
            break
    return response

