async def group_int_or_str_attribute(provider_child_map: dict[str, ProviderChild], number_of_children_resource_on: int, provider_child_resources: Union[dict, list[dict]], provider_child_key_id: str, included_children_key: str, key: Union[int, str]) -> Union[int, str, list[dict]]:
    if isinstance(provider_child_resources, list):
        grouped_attribute = await base_group_str_attribute(provider_child_map, provider_child_resources, provider_child_key_id)
    else:
        grouped_attribute = base_group_int_attribute(provider_child_resources, provider_child_key_id)
    if len(grouped_attribute) == 1:
        return list(grouped_attribute.keys())[0]
    response = []
    grouped_attribute = await set_included_provider_children_for_grouped_attribute(provider_child_map, number_of_children_resource_on, provider_child_key_id, included_children_key, grouped_attribute)
    for (resource_val, included_accounts) in grouped_attribute.items():
        if included_accounts[0] == '*':
            response.append({key: resource_val})
        else:
            response.append({key: resource_val, 'included_accounts': included_accounts})
    return response

