def print_tree(root, child_func, prune: bool=False, showtags: int=0, margin: List[bool]=[False], visited: Optional[dict]=None, lastChild: bool=False, singleLineDraw: bool=False) -> None:
    rname = str(root)
    if visited is None:
        visited = {}
    if showtags:
        if showtags == 2:
            legend = ' E         = exists\n' + '  R        = exists in repository only\n' + '   b       = implicit builder\n' + '   B       = explicit builder\n' + '    S      = side effect\n' + '     P     = precious\n' + '      A    = always build\n' + '       C   = current\n' + '        N  = no clean\n' + '         H = no cache\n' + '\n'
            sys.stdout.write(legend)
        tags = ['[', ' E'[IDX(root.exists())], ' R'[IDX(root.rexists() and (not root.exists()))], ' BbB'[[0, 1][IDX(root.has_explicit_builder())] + [0, 2][IDX(root.has_builder())]], ' S'[IDX(root.side_effect)], ' P'[IDX(root.precious)], ' A'[IDX(root.always_build)], ' C'[IDX(root.is_up_to_date())], ' N'[IDX(root.noclean)], ' H'[IDX(root.nocache)], ']']
    else:
        tags = []

    def MMM(m):
        if singleLineDraw:
            return ['  ', BOX_VERT + ' '][m]
        return ['  ', '| '][m]
    margins = list(map(MMM, margin[:-1]))
    children = child_func(root)
    cross = '+-'
    if singleLineDraw:
        cross = BOX_VERT_RIGHT + BOX_HORIZ
        if lastChild:
            cross = BOX_UP_RIGHT + BOX_HORIZ
        if children:
            if prune and rname in visited and children:
                cross += BOX_HORIZ
            else:
                cross += BOX_HORIZ_DOWN
    if prune and rname in visited and children:
        sys.stdout.write(''.join(tags + margins + [cross, '[', rname, ']']) + '\n')
        return
    sys.stdout.write(''.join(tags + margins + [cross, rname]) + '\n')
    visited[rname] = 1
    if children:
        margin.append(True)
        idx = IDX(showtags)
        _child = 0
        for C in children[:-1]:
            _child = _child + 1
            print_tree(C, child_func, prune, idx, margin, visited, len(children) - _child <= 0, singleLineDraw)
        margin[-1] = False
        print_tree(children[-1], child_func, prune, idx, margin, visited, True, singleLineDraw)
        margin.pop()

