def service_to_instances(service, version):
    service_instances = []
    for binding in service.supported_protocol_bindings:
        address = service.absolute_address(binding)
        if version == 10:
            stype = service.service_type
            if stype == SVC_COLLECTION_MANAGEMENT:
                stype = SVC_FEED_MANAGEMENT
            instance = tm10.ServiceInstance(service_type=stype, services_version=VID_TAXII_SERVICES_10, available=service.enabled, protocol_binding=binding, service_address=address, message_bindings=service.supported_message_bindings, message=service.description)
        elif version == 11:
            instance = tm11.ServiceInstance(service_type=service.service_type, services_version=VID_TAXII_SERVICES_11, available=service.enabled, protocol_binding=binding, service_address=address, message_bindings=service.supported_message_bindings, message=service.description)
        service_instances.append(instance)
    return service_instances

