def _format_arg(self, opt, spec, val):
    if opt == 'fixed_image_mask':
        if isdefined(self.inputs.moving_image_mask):
            return '--masks [ %s, %s ]' % (self.inputs.fixed_image_mask, self.inputs.moving_image_mask)
        else:
            return '--masks %s' % self.inputs.fixed_image_mask
    elif opt == 'transforms':
        return self._formatRegistration()
    elif opt == 'initial_moving_transform':
        try:
            doInvertTransform = int(self.inputs.invert_initial_moving_transform)
        except:
            doInvertTransform = 0
        return '--initial-moving-transform [ %s, %d ]' % (self.inputs.initial_moving_transform, doInvertTransform)
    elif opt == 'initial_moving_transform_com':
        try:
            doCenterOfMassInit = int(self.inputs.initial_moving_transform_com)
        except:
            doCenterOfMassInit = 0
        return '--initial-moving-transform [ %s, %s, %d ]' % (self.inputs.fixed_image[0], self.inputs.moving_image[0], doCenterOfMassInit)
    elif opt == 'interpolation':
        if self.inputs.interpolation in ['BSpline', 'MultiLabel', 'Gaussian'] and isdefined(self.inputs.interpolation_parameters):
            return '--interpolation %s[ %s ]' % (self.inputs.interpolation, ', '.join([str(param) for param in self.inputs.interpolation_parameters]))
        else:
            return '--interpolation %s' % self.inputs.interpolation
    elif opt == 'output_transform_prefix':
        out_filename = self._get_outputfilenames(inverse=False)
        inv_out_filename = self._get_outputfilenames(inverse=True)
        if out_filename and inv_out_filename:
            return '--output [ %s, %s, %s ]' % (self.inputs.output_transform_prefix, out_filename, inv_out_filename)
        elif out_filename:
