def train_step(self, inputs, model: tf.keras.Model, optimizer: tf.keras.optimizers.Optimizer, metrics):
    with tf.GradientTape() as tape:
        outputs = model(inputs, training=True)
        loss = self.build_losses(labels=inputs, model_outputs=outputs, metrics=metrics, aux_losses=model.losses)
        if self.task_config.scale_loss:
            scaled_loss = loss / tf.distribute.get_strategy().num_replicas_in_sync
    tvars = model.trainable_variables
    if self.task_config.scale_loss:
        grads = tape.gradient(scaled_loss, tvars)
    else:
        grads = tape.gradient(loss, tvars)
    optimizer.apply_gradients(list(zip(grads, tvars)))
    self.process_metrics(metrics, inputs, outputs)
    return {self.loss: loss}

def _prepare_aggregations(self, sort_field: str, start: datetime, end: datetime, having: Sequence[Sequence[Any]], aggregate_kwargs: Optional[PrioritySortWeights]=None) -> list[Any]:
    extra_aggregations = self.dependency_aggregations.get(sort_field, [])
    required_aggregations = set([sort_field, 'total'] + extra_aggregations)
    for h in having:
        alias = h[0]
        required_aggregations.add(alias)
    aggregations = []
    for alias in required_aggregations:
        aggregation = self.aggregation_defs[alias]
        if callable(aggregation):
            if aggregate_kwargs:
                aggregation = aggregation(start, end, aggregate_kwargs.get(alias, {}))
            else:
                aggregation = aggregation(start, end)
        aggregations.append(aggregation + [alias])
    return aggregations

